style.css:
* {
  transition: all 0.3s ease !important;
}

/* Fondo crema elegante */
body {
  background: #f4efe6 !important;
  color: #2b2b2b !important;
  font-family: Georgia, 'Times New Roman', serif !important;
}

/* Títulos elegantes */
h1, h2, h3 {
  letter-spacing: 1px !important;
  color: #1f1f1f !important;
}

/* Tarjetas finas */
div, section {
  background: #ffffff !important;
  border-radius: 12px !important;
  border: 1px solid #e0d6c2 !important;
  box-shadow: 0 6px 25px rgba(0,0,0,0.05) !important;
  padding: 10px !important;
}

/* Borde dorado al pasar el mouse */
div:hover, section:hover {
  border: 1px solid #c9a24d !important;
  transform: translateY(-3px);
}

/* Botones Old Money */
button {
  background: #1f1f1f !important;
  color: #f4efe6 !important;
  border-radius: 6px !important;
  border: none !important;
  padding: 8px 12px !important;
}

button:hover {
  background: #c9a24d !important;
  color: #1f1f1f !important;
}

/* Links dorados */
a {
  color: #b38b2d !important;
  text-decoration: none !important;
}

/* Imágenes con marco fino */
img {
  border-radius: 10px !important;
  border: 2px solid #e0d6c2 !important;
}
